    const group = new THREE.Group();

    // 🌍 BUILD OPEN WORLD FLOOR (große grüne Fläche)
    const floorGeo = new THREE.PlaneGeometry(OPEN_WORLD_SIZE, OPEN_WORLD_SIZE, 100, 100);
    const floorMat = new THREE.MeshStandardMaterial({
        color: 0x3f7a2c, // Grasgrün
        roughness: 0.95,
        metalness: 0.0
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    group.add(floor);

    // 🏠 BUILD GEBÄUDE (6 Stück als Cubes - später GLTF)
    const buildings = [
        { name: 'Schwarze Mühle', pos: [0, 0, 0], size: 80, color: 0x8b4513 },
        { name: 'Kampfarena', pos: [-600, 0, -600], size: 50, color: 0xaa1111 },
        { name: 'Garten', pos: [600, 0, 600], size: 60, color: 0x228b22 },
        { name: 'Dungeon 1', pos: [-720, 0, -720], size: 70, color: 0x555555 },
        { name: 'Dungeon 2', pos: [720, 0, -720], size: 70, color: 0x666666 },
        { name: 'Dungeon 3', pos: [0, 0, 720], size: 70, color: 0x777777 }
    ];

    buildings.forEach(b => {
        const geo = new THREE.BoxGeometry(b.size, 50, b.size);
        const mat = new THREE.MeshStandardMaterial({ color: b.color });
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(b.pos[0], 25, b.pos[2]);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.userData.buildingName = b.name;
        group.add(mesh);
    });

    roomGroup = group;
    scene.add(roomGroup);

    // Palette für Open World (blauer Himmel)
    applyPalette({ background: 0x87CEEB, fog: 0xb5d8e0, ambient: 0.6 });

    // Character spawnt in Mitte
    resetCharacterPosition([0, 0, 0]);
}

