   505→        // Skaliere Boden auf volle span-Größe
   506→        scaleUniformToSpan(instance, span);
   507→        // Mache Boden EXTREM flach (nur 5% Höhe) wie eine dünne Platte
   508→        instance.scale.y *= 0.05;
   509→        // Berechne BoundingBox um Boden korrekt zu positionieren
   510→        const box = new THREE.Box3().setFromObject(instance);
   511→        const floorHeight = box.max.y - box.min.y;
   512→        // Positioniere so dass OBERSEITE bei Y=0 ist (Unterseite darunter)
   513→        instance.position.y = -box.min.y - floorHeight;
   514→        applyEntryTransform(instance, entry);
   515→        return instance;
