   518→    function buildWalls(entry, span, wallHeight) {
   519→        const base = makeModelInstance(entry);
   520→        if (!base) return null;
   521→
   522→        // Skaliere Wand-Modell auf die volle span-Breite
   523→        scaleAxisToSpan(base, 'x', span);
   524→
   525→        const group = new THREE.Group();
   526→        // Wände am RAND des Bodens positionieren (span / 2)
   527→        const half = span / 2;
   528→
   529→        const north = cloneGroup(base);
   530→        north.position.set(0, 0, -half);
   531→        group.add(north);
   532→
   533→        const south = cloneGroup(base);
   534→        south.rotation.y = Math.PI;
   535→        south.position.set(0, 0, half);
   536→        group.add(south);
   537→
   538→        const east = cloneGroup(base);
   539→        east.rotation.y = -Math.PI / 2;
   540→        east.position.set(half, 0, 0);
   541→        group.add(east);
   542→
   543→        const west = cloneGroup(base);
   544→        west.rotation.y = Math.PI / 2;
   545→        west.position.set(-half, 0, 0);
   546→        group.add(west);
   547→
   548→        group.traverse(node => {
   549→            if (node.isMesh) {
   550→                node.castShadow = true;
   551→                node.receiveShadow = true;
   552→            }
   553→        });
   554→
   555→        // Skaliere Wand-Höhe auf gewünschte wallHeight
   556→        const currentHeight = getBoundingSize(group).y;
   557→        const scaleFactor = wallHeight / Math.max(currentHeight, 0.0001);
   558→        group.scale.y *= scaleFactor;
   559→
   560→        // WICHTIG: Wände mit UNTERSEITE auf Y=0 (Boden-Oberseite)
   561→        const box = new THREE.Box3().setFromObject(group);
   562→        group.position.y = -box.min.y;
