   665→        } else if (Array.isArray(entry.scale)) {
   666→            const [sx = 1, sy = 1, sz = 1] = entry.scale;
   667→            group.scale.x *= sx;
   668→            group.scale.y *= sy;
   669→            group.scale.z *= sz;
   670→        }
   671→
   672→        if (Array.isArray(entry.rotation)) {
   673→            const [rx = 0, ry = 0, rz = 0] = entry.rotation;
   674→            group.rotation.set(rx, ry, rz);
   675→        }
   676→
   677→        if (Array.isArray(entry.position)) {
   678→            const [px = 0, py = 0, pz = 0] = entry.position;
   679→            // Nur X und Z setzen, Y wird durch adjustToGround() bestimmt
   680→            group.position.x += px;
   681→            group.position.z += pz;
   682→            // Y-Offset wird NACH adjustToGround angewendet
   683→            if (py !== 0) {
   684→                group.position.y += py;
