   797→    function updateCharacter(delta) {
   798→        if (!characterGroup) return;
   799→
   800→        // Input relativ zum Spieler (lokal)
   801→        let forward = 0;
   802→        let right = 0;
   803→
   804→        // Third & Orbit: W/S vertauscht | First: A/D vertauscht
   805→        if (cameraMode === CAMERA_MODES.FIRST) {
   806→            // FIRST: A/D vertauscht
   807→            if (activeKeys.has('KeyW') || activeKeys.has('ArrowUp')) forward += 1;
   808→            if (activeKeys.has('KeyS') || activeKeys.has('ArrowDown')) forward -= 1;
   809→            if (activeKeys.has('KeyA') || activeKeys.has('ArrowLeft')) right += 1;  // VERTAUSCHT
   810→            if (activeKeys.has('KeyD') || activeKeys.has('ArrowRight')) right -= 1;  // VERTAUSCHT
   811→        } else {
   812→            // THIRD & ORBIT: W/S vertauscht
   813→            if (activeKeys.has('KeyW') || activeKeys.has('ArrowUp')) forward -= 1;  // VERTAUSCHT
   814→            if (activeKeys.has('KeyS') || activeKeys.has('ArrowDown')) forward += 1;  // VERTAUSCHT
   815→            if (activeKeys.has('KeyA') || activeKeys.has('ArrowLeft')) right -= 1;
   816→            if (activeKeys.has('KeyD') || activeKeys.has('ArrowRight')) right += 1;
   817→        }
   818→
   819→        if (forward !== 0 || right !== 0) {
   820→            // FORTNITE-Style: WASD relativ zur KAMERA (orbitYaw)
   821→            const inputAngle = Math.atan2(right, forward);
   822→            const worldAngle = orbitYaw + inputAngle;
   823→
   824→            // Bewegungsvektor in Weltkoordinaten
   825→            const moveX = Math.sin(worldAngle);
   826→            const moveZ = Math.cos(worldAngle);
   827→
   828→            const speed = CHARACTER_SPEED * (cameraMode === CAMERA_MODES.FIRST ? 0.9 : 1);
   829→            characterGroup.position.x += moveX * speed * delta;
   830→            characterGroup.position.z += moveZ * speed * delta;
   831→            clampCharacterToRoom(characterGroup.position);
   832→
   833→            // Charakter dreht sich in Bewegungsrichtung
   834→            characterHeading = worldAngle;
   835→            characterGroup.rotation.y = characterHeading;
   836→        }
   837→    }
