   845→    function getCameraTarget() {
   846→        if (characterGroup) {
   847→            return characterGroup.position.clone().add(new THREE.Vector3(0, CHARACTER_HEIGHT * 0.85, 0));
   848→        }
   849→        return new THREE.Vector3(0, 0, 0);
