   852→    function updateCamera(delta) {
   853→        if (!camera) return;
   854→
   855→        const target = getCameraTarget();
   856→        const cosPitch = Math.cos(orbitPitch);
   857→        const sinPitch = Math.sin(orbitPitch);
   858→        const cosYaw = Math.cos(orbitYaw);
   859→        const sinYaw = Math.sin(orbitYaw);
   860→
   861→        if (cameraMode === CAMERA_MODES.ORBIT || !characterGroup) {
   862→            // ORBIT Mode: Freie Kamera-Steuerung
   863→            const offset = new THREE.Vector3(
   864→                sinYaw * cosPitch,
   865→                sinPitch,
   866→                cosYaw * cosPitch
   867→            ).multiplyScalar(orbitDistance);
   868→            camera.position.copy(target).add(offset);
   869→            camera.lookAt(target);
   870→        } else if (cameraMode === CAMERA_MODES.THIRD) {
   871→            // THIRD: Kamera wie Orbit, nur näher (Fortnite-Style: Maus steuert Kamera)
   872→            const distance = 12;
   873→            const height = 4;
   874→            const offset = new THREE.Vector3(
   875→                sinYaw * cosPitch * distance,
   876→                height + sinPitch * distance * 0.5,
   877→                cosYaw * cosPitch * distance
   878→            );
   879→            camera.position.copy(target).add(offset);
   880→            camera.lookAt(target);
   881→        } else if (cameraMode === CAMERA_MODES.FIRST) {
   882→            // FIRST: Kamera DIREKT am Kopf (Augen), Blickrichtung = orbitYaw/Pitch
   883→            const eyeHeight = CHARACTER_HEIGHT * 0.85;
   884→
   885→            // Kamera DIREKT am Kopf (keine Offset-Berechnung nötig)
   886→            camera.position.set(
   887→                characterGroup.position.x,
   888→                characterGroup.position.y + eyeHeight,
   889→                characterGroup.position.z
   890→            );
   891→
   892→            // Blickrichtung folgt MAUS (orbitYaw und orbitPitch)
   893→            const lookDistance = 10;
   894→            const lookTarget = new THREE.Vector3(
   895→                camera.position.x + sinYaw * cosPitch * lookDistance,
   896→                camera.position.y + sinPitch * lookDistance,
   897→                camera.position.z + cosYaw * cosPitch * lookDistance
   898→            );
   899→            camera.lookAt(lookTarget);
   900→        }
   901→    }
