    buildingPromptUI.style.cssText = `
        position: fixed;
        bottom: 150px;
        left: 50%;
        transform: translateX(-50%);
        background: rgba(0,0,0,0.9);
        border: 3px solid #ffffff;
        border-radius: 15px;
