(function() {
    const GARDEN_CONFIG = {
        // 9 Beete im Garten (3x3 Grid)
        plots: [
            { id: 1, position: [-50, 0, -50], size: 20 },
            { id: 2, position: [0, 0, -50], size: 20 },
            { id: 3, position: [50, 0, -50], size: 20 },
            { id: 4, position: [-50, 0, 0], size: 20 },
            { id: 5, position: [0, 0, 0], size: 20 },
            { id: 6, position: [50, 0, 0], size: 20 },
            { id: 7, position: [-50, 0, 50], size: 20 },
            { id: 8, position: [0, 0, 50], size: 20 },
            { id: 9, position: [50, 0, 50], size: 20 }
        ],

        // Pflanzen mit 5 Wachstumsstufen
        plants: {
            karotte: {
                name: 'Karotte',
                stages: 5,
                growTime: 60,  // seconds per stage
                harvestYield: 3,
                sellPrice: 15,
                uses: ['kochen', 'verkaufen', 'heilen']
            },
            tomate: {
                name: 'Tomate',
                stages: 5,
                growTime: 80,
                harvestYield: 4,
                sellPrice: 20,
                uses: ['kochen', 'verkaufen']
            },
            weizen: {
                name: 'Weizen',
                stages: 5,
                growTime: 50,
                harvestYield: 5,
                sellPrice: 10,
                uses: ['kochen', 'crafting']
            },
            heilkraut: {
                name: 'Heilkraut',
                stages: 5,
                growTime: 120,
