            for (const [seedType, seedConfig] of Object.entries(GARDEN_CONFIG.seeds)) {
                const plantConfig = GARDEN_CONFIG.plants[seedConfig.plant];
                const canAfford = inventory.gold >= seedConfig.cost;

                html += `
