// 🏠 BUILDING INTERIOR SYSTEM
let currentInterior = null;
let exteriorPosition = null;

function enterBuilding() {
    if (!nearBuilding) return false;

    const buildingName = nearBuilding.userData.buildingName;
    console.log(`🚪 Betrete Gebäude: ${buildingName}`);

    if (typeof notify === 'function') {
        notify(`🚪 ${buildingName} betreten!`, 'info');
    }

    // Speichere Position draußen
    exteriorPosition = {
        x: characterGroup.position.x,
        y: characterGroup.position.y,
        z: characterGroup.position.z
    };

    // Lade Interior
    loadBuildingInterior(buildingName);
    return true;
}

function loadBuildingInterior(buildingName) {
    // Entferne Open World
    if (roomGroup) {
        scene.remove(roomGroup);
    }

    // Erstelle Interior Group
    const interiorGroup = new THREE.Group();
    currentInterior = buildingName;

    // Gebäude-spezifische Interiors
    if (buildingName === 'Schwarze Mühle') {
        createSchwarzerMuehleInterior(interiorGroup);
    } else if (buildingName === 'Kampfarena') {
        createKampfarenaInterior(interiorGroup);
    } else if (buildingName === 'Garten') {
        createGartenHouseInterior(interiorGroup);
    } else if (buildingName.includes('Dungeon')) {
        createDungeonInterior(interiorGroup, buildingName);
    } else {
        // Fallback: Generic Interior
        createGenericInterior(interiorGroup);
    }

    roomGroup = interiorGroup;
    scene.add(roomGroup);

    // Spawn Charakter in Mitte des Raums
    resetCharacterPosition([0, 0, 0]);

    // Dunkle Palette für Interior
    applyPalette({ background: 0x2a2a3a, fog: 0x1a1a2a, ambient: 0.4 });

    // Zeige Exit-Button
    showExitBuildingPrompt();
}

function exitBuilding() {
    if (!currentInterior) return;

    console.log(`🚪 Verlasse Gebäude: ${currentInterior}`);

    // Entferne Interior
    if (roomGroup) {
        scene.remove(roomGroup);
    }

    currentInterior = null;

    // Lade Open World zurück
    buildRoom();

    // Restore Position draußen
    if (exteriorPosition) {
        characterGroup.position.set(
            exteriorPosition.x,
            exteriorPosition.y,
            exteriorPosition.z
        );
    }

    hideExitBuildingPrompt();
}

// === INTERIOR BUILDERS ===

function createSchwarzerMuehleInterior(group) {
    // Boden (60x60)
    const floorGeo = new THREE.PlaneGeometry(60, 60);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x3a2a1a, roughness: 0.9 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    group.add(floor);

    // Wände (4 Seiten)
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x5a4a3a, roughness: 0.8 });
    const walls = [
        { pos: [0, 15, -30], rot: 0, size: [60, 30, 2] },
        { pos: [0, 15, 30], rot: 0, size: [60, 30, 2] },
        { pos: [-30, 15, 0], rot: Math.PI/2, size: [60, 30, 2] },
        { pos: [30, 15, 0], rot: Math.PI/2, size: [60, 30, 2] }
    ];
    walls.forEach(w => {
        const wallGeo = new THREE.BoxGeometry(...w.size);
        const wall = new THREE.Mesh(wallGeo, wallMat);
        wall.position.set(...w.pos);
        wall.rotation.y = w.rot;
        wall.castShadow = true;
        wall.receiveShadow = true;
        group.add(wall);
    });

    // Möbel (Tisch + Stühle)
    const tableMat = new THREE.MeshStandardMaterial({ color: 0x8b4513 });
    const tableGeo = new THREE.BoxGeometry(10, 2, 6);
    const table = new THREE.Mesh(tableGeo, tableMat);
    table.position.set(0, 1, 0);
    table.castShadow = true;
    group.add(table);
}

function createKampfarenaInterior(group) {
    // Arena-Boden (80x80)
    const floorGeo = new THREE.PlaneGeometry(80, 80);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x4a3a2a, roughness: 0.95 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    group.add(floor);

    // Arena-Wände
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x6a5a4a, roughness: 0.9 });
    const walls = [
        { pos: [0, 20, -40], rot: 0, size: [80, 40, 2] },
        { pos: [0, 20, 40], rot: 0, size: [80, 40, 2] },
        { pos: [-40, 20, 0], rot: Math.PI/2, size: [80, 40, 2] },
        { pos: [40, 20, 0], rot: Math.PI/2, size: [80, 40, 2] }
    ];
    walls.forEach(w => {
        const wallGeo = new THREE.BoxGeometry(...w.size);
        const wall = new THREE.Mesh(wallGeo, wallMat);
        wall.position.set(...w.pos);
        wall.rotation.y = w.rot;
        wall.castShadow = true;
        group.add(wall);
    });
}

function createGartenHouseInterior(group) {
    // Kleines Gartenhaus (40x40)
    const floorGeo = new THREE.PlaneGeometry(40, 40);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x2a4a2a, roughness: 0.9 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    group.add(floor);

    // Grüne Wände
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x3a6a3a, roughness: 0.8 });
    const walls = [
        { pos: [0, 12, -20], rot: 0, size: [40, 24, 2] },
        { pos: [0, 12, 20], rot: 0, size: [40, 24, 2] },
        { pos: [-20, 12, 0], rot: Math.PI/2, size: [40, 24, 2] },
        { pos: [20, 12, 0], rot: Math.PI/2, size: [40, 24, 2] }
    ];
    walls.forEach(w => {
        const wallGeo = new THREE.BoxGeometry(...w.size);
        const wall = new THREE.Mesh(wallGeo, wallMat);
        wall.position.set(...w.pos);
        wall.rotation.y = w.rot;
        wall.castShadow = true;
        group.add(wall);
    });
}

function createDungeonInterior(group, dungeonName) {
    // Dunkler Dungeon (70x70)
    const floorGeo = new THREE.PlaneGeometry(70, 70);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x1a1a2a, roughness: 1.0 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    group.add(floor);

    // Steinwände
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3a, roughness: 0.95 });
    const walls = [
        { pos: [0, 18, -35], rot: 0, size: [70, 36, 2] },
        { pos: [0, 18, 35], rot: 0, size: [70, 36, 2] },
        { pos: [-35, 18, 0], rot: Math.PI/2, size: [70, 36, 2] },
        { pos: [35, 18, 0], rot: Math.PI/2, size: [70, 36, 2] }
    ];
    walls.forEach(w => {
        const wallGeo = new THREE.BoxGeometry(...w.size);
        const wall = new THREE.Mesh(wallGeo, wallMat);
        wall.position.set(...w.pos);
        wall.rotation.y = w.rot;
        wall.castShadow = true;
        group.add(wall);
    });
}

function createGenericInterior(group) {
    // Generic Interior (50x50)
    const floorGeo = new THREE.PlaneGeometry(50, 50);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x4a4a5a, roughness: 0.9 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    group.add(floor);

    const wallMat = new THREE.MeshStandardMaterial({ color: 0x5a5a6a, roughness: 0.8 });
    const walls = [
        { pos: [0, 15, -25], rot: 0, size: [50, 30, 2] },
        { pos: [0, 15, 25], rot: 0, size: [50, 30, 2] },
        { pos: [-25, 15, 0], rot: Math.PI/2, size: [50, 30, 2] },
        { pos: [25, 15, 0], rot: Math.PI/2, size: [50, 30, 2] }
    ];
    walls.forEach(w => {
        const wallGeo = new THREE.BoxGeometry(...w.size);
        const wall = new THREE.Mesh(wallGeo, wallMat);
        wall.position.set(...w.pos);
        wall.rotation.y = w.rot;
        wall.castShadow = true;
        group.add(wall);
    });
}

// Exit Building Prompt
let exitBuildingPromptUI = null;

function showExitBuildingPrompt() {
    if (!exitBuildingPromptUI) {
        exitBuildingPromptUI = document.createElement('div');
        exitBuildingPromptUI.id = 'exit-building-prompt-ui';
        exitBuildingPromptUI.style.cssText = `
            position: fixed;
            bottom: 100px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0,0,0,0.9);
            border: 2px solid #ff6b9d;
            border-radius: 10px;
            padding: 15px 25px;
            color: white;
            font-family: monospace;
            font-size: 16px;
            z-index: 1500;
            text-align: center;
        `;
        exitBuildingPromptUI.innerHTML = `
            🚪 Drücke [Q] um Gebäude zu verlassen
        `;
        document.body.appendChild(exitBuildingPromptUI);
    }
    exitBuildingPromptUI.style.display = 'block';
}

function hideExitBuildingPrompt() {
    if (exitBuildingPromptUI) {
        exitBuildingPromptUI.style.display = 'none';
    }
}

