function createGardenUI() {
    gardenUI = document.createElement('div');
    gardenUI.id = 'garden-ui';
    gardenUI.style.cssText = `
        position: fixed;
        top: 20px;
        left: 20px;
        background: rgba(0,0,0,0.8);
        border: 3px solid #50c878;
        border-radius: 15px;
        padding: 15px;
        color: white;
        font-family: monospace;
        font-size: 12px;
        display: none;
        z-index: 1000;
        max-width: 300px;
    `;

    gardenUI.innerHTML = `
        <div style="position: relative;">
            <button id="garden-close-btn" style="
                position: absolute;
                top: -5px;
                right: -5px;
                background: #ff6b9d;
                color: white;
                border: none;
                border-radius: 50%;
                width: 25px;
                height: 25px;
                font-size: 16px;
                font-weight: bold;
                cursor: pointer;
                line-height: 1;
                padding: 0;
            ">✖</button>
        </div>
        <div style="font-size: 16px; margin-bottom: 10px; text-align: center;">
            🌱 Garten
        </div>
        <div id="garden-plot-info" style="margin-bottom: 10px;">
            Kein Beet ausgewählt
        </div>
        <div style="margin-bottom: 10px;">
            <strong>Inventar:</strong>
            <div id="garden-inventory" style="margin-top: 5px; font-size: 11px;"></div>
        </div>
        <div>
            <strong>💧 Gießkanne:</strong>
            <div style="background: #333; height: 10px; border-radius: 5px; overflow: hidden; margin-top: 3px;">
                <div id="water-bar" style="background: #4a90e2; height: 100%; width: 100%;"></div>
            </div>
        </div>
        <div style="margin-top: 10px; font-size: 11px; color: #aaa;">
            E: Pflanzen/Ernten | R: Gießen | ESC: Schließen
        </div>
    `;

    document.body.appendChild(gardenUI);

    // Close button handler
    const closeBtn = gardenUI.querySelector('#garden-close-btn');
    if (closeBtn) {
        closeBtn.addEventListener('click', hideGardenUI);
    }

    // ESC key handler for garden UI
    document.addEventListener('keydown', (e) => {
        if (e.code === 'Escape' && gardenUI && gardenUI.style.display === 'block') {
            hideGardenUI();
        }
    });

    // Create Shop UI
    createShopUI();
}

let shopUI = null;

