            this.checkCombo();
            return true;
        },

        attackRight() {
            if (this.stamina < 15) return false;
            this.stamina -= 15;
            this.comboBuffer += 'R';
            this.checkCombo();
            return true;
        },

        parry() {
            const now = Date.now();
            if (now - this.lastParryTime < 1000) return false;  // Cooldown
            this.isParrying = true;
            this.lastParryTime = now;
            setTimeout(() => { this.isParrying = false; }, this.parryWindow.end);
