                Drücke SPACE zum Einholen
            </div>
        `;

        document.body.appendChild(fishingUI);
    }

    function showFishingUI() {
        if (!fishingUI) return;
        fishingUI.style.display = 'block';
    }

    function hideFishingUI() {
        if (!fishingUI) return;
        fishingUI.style.display = 'none';
