function createDungeonInterior(group, dungeonName) {
    // Dunkler Dungeon (70x70)
    const floorGeo = new THREE.PlaneGeometry(70, 70);
    const floorMat = new THREE.MeshStandardMaterial({ color: 0x1a1a2a, roughness: 1.0 });
