    // Load room configs from JSON
    async function loadRoomConfigs() {
        if (roomConfigs) return roomConfigs;
        try {
            const response = await fetch('/assets/room_config_detailed.json');
            roomConfigs = await response.json();
            console.log('✅ Room configs loaded:', roomConfigs.rooms.length, 'rooms');
            return roomConfigs;
        } catch (err) {
            console.error('❌ Failed to load room configs:', err);
            return null;
        }
    }

    function enterBuilding() {
        if (!nearBuilding) return false;

        const buildingName = nearBuilding.userData.buildingName;
        console.log(`🚪 Betrete Gebäude: ${buildingName}`);

        if (typeof notify === 'function') {
            notify(`🚪 ${buildingName} betreten!`, 'info');
        }

        // Speichere Position draußen
        exteriorPosition = {
            x: characterGroup.position.x,
            y: characterGroup.position.y,
            z: characterGroup.position.z
        };

        // Lade Interior
        loadBuildingInterior(buildingName);
        return true;
    }

    function loadBuildingInterior(buildingName) {
        // Entferne Open World
        if (roomGroup) {
            scene.remove(roomGroup);
        }

        // Erstelle Interior Group
        const interiorGroup = new THREE.Group();
        currentInterior = buildingName;

        // Gebäude-spezifische Interiors
        if (buildingName === 'Schwarze Mühle') {
            createSchwarzerMuehleInterior(interiorGroup);
        } else if (buildingName === 'Kampfarena') {
            createKampfarenaInterior(interiorGroup);
        } else if (buildingName === 'Garten') {
            createGartenHouseInterior(interiorGroup);
        } else if (buildingName.includes('Dungeon')) {
            createDungeonInterior(interiorGroup, buildingName);
        } else {
            // Fallback: Generic Interior
            createGenericInterior(interiorGroup);
        }

        roomGroup = interiorGroup;
        scene.add(roomGroup);

        // Spawn Charakter in Mitte des Raums
        resetCharacterPosition([0, 0, 0]);

        // Dunkle Palette für Interior
        applyPalette({ background: 0x2a2a3a, fog: 0x1a1a2a, ambient: 0.4 });

        // Zeige Exit-Button
        showExitBuildingPrompt();
    }

    function exitBuilding() {
        if (!currentInterior) return;

        console.log(`🚪 Verlasse Gebäude: ${currentInterior}`);

        // Entferne Interior
        if (roomGroup) {
            scene.remove(roomGroup);
        }

        currentInterior = null;

        // Lade Open World zurück
        buildRoom();

        // Restore Position draußen
        if (exteriorPosition) {
            characterGroup.position.set(
                exteriorPosition.x,
                exteriorPosition.y,
                exteriorPosition.z
            );
        }

        hideExitBuildingPrompt();
    }

