    function setupFallbackRoom() {
        const floorGeometry = new THREE.PlaneGeometry(120, 120);
        const floorMaterial = new THREE.MeshStandardMaterial({
            color: DEFAULT_PALETTE.floor,
            roughness: 0.85,
            metalness: 0.1
