    async function loadMuehleFloor(floorIndex) {
        const configs = await loadRoomConfigs();
        const floor = muehleFloors[floorIndex];
        let roomConfig = configs.rooms.find(r => r.name === floor.room);

        if (!roomConfig) {
            console.error(`❌ Room config not found: ${floor.room}`);
            return;
