input.old_string:
async function loadRoomFloor(group, floorConfig, span) {
    if (!THREE.GLTFLoader) {
        console.warn('GLTFLoader not available');
        return;
    }

    const loader = new THREE.GLTFLoader();
    return new Promise((resolve) => {
        loader.load(
            `/assets/${floorConfig.model}`,
            (gltf) => {
                const count = Math.ceil(span / 12);  // 12 units per tile
                for (let x = -count/2; x < count/2; x++) {
                    for (let z = -count/2; z < count/2; z++) {
                        const tile = gltf.scene.clone();
                        tile.position.set(x * 12, 0, z * 12);
                        tile.traverse(node => {
                            if (node.isMesh) {
                                node.receiveShadow = true;
                                if (floorConfig.tint) {
                                    node.material = node.material.clone();
                                    node.material.color.setStyle(floorConfig.tint);
                                    node.material.roughness = floorConfig.roughness || 0.8;
                                    node.material.metalness = floorConfig.metalness || 0.1;
                                }
                            }
                        });
                        group.add(tile);
                    }
                }
                resolve();
            },
            undefined,
            (error) => {
                console.error('Error loading floor:', error);
                resolve();
            }
        );
    });
}

