async function loadRoomWalls(group, wallConfig, span, wallHeight) {
    if (!THREE.GLTFLoader) return;

    const loader = new THREE.GLTFLoader();
    const halfSpan = span / 2;
    const wallCount = Math.ceil(span / 12);

    const wallPositions = [
        { pos: [0, wallHeight/2, -halfSpan], rot: 0, dir: 'z', count: wallCount },
        { pos: [0, wallHeight/2, halfSpan], rot: Math.PI, dir: 'z', count: wallCount },
        { pos: [-halfSpan, wallHeight/2, 0], rot: Math.PI/2, dir: 'x', count: wallCount },
        { pos: [halfSpan, wallHeight/2, 0], rot: -Math.PI/2, dir: 'x', count: wallCount }
    ];

    for (const wallPos of wallPositions) {
        for (let i = 0; i < wallPos.count; i++) {
            await new Promise((resolve) => {
                loader.load(
                    `/assets/${wallConfig.model}`,
                    (gltf) => {
                        const wall = gltf.scene.clone();
                        const offset = (i - wallPos.count/2) * 12 + 6;
                        if (wallPos.dir === 'z') {
                            wall.position.set(offset, wallPos.pos[1], wallPos.pos[2]);
                        } else {
                            wall.position.set(wallPos.pos[0], wallPos.pos[1], offset);
                        }
                        wall.rotation.y = wallPos.rot;
                        wall.traverse(node => {
                            if (node.isMesh) {
                                node.castShadow = true;
                                node.receiveShadow = true;
                                if (wallConfig.tint) {
                                    node.material = node.material.clone();
                                    node.material.color.setStyle(wallConfig.tint);
                                }
                            }
                        });
                        group.add(wall);
                        resolve();
                    },
                    undefined,
                    () => resolve()
                );
            });
        }
    }
}

