            { id: 4, position: [550, 0, 600], size: 20 },
            { id: 5, position: [600, 0, 600], size: 20 },
            { id: 6, position: [650, 0, 600], size: 20 },
            { id: 7, position: [550, 0, 650], size: 20 },
            { id: 8, position: [600, 0, 650], size: 20 },
