    async function loadBuildingInterior(buildingName) {
        // Lade Room Configs
        const configs = await loadRoomConfigs();
        if (!configs) {
            console.error('❌ No room configs available');
            return;
        }

        // Entferne Open World
        if (roomGroup) {
            scene.remove(roomGroup);
