// Najika Digivice – Three.js scene manager with KayKit rooms, character controls and camera modes
(function () {
    const CAMERA_MODES = {
        ORBIT: 'orbit',
        THIRD: 'third',
        FIRST: 'first'
    };

    const DEFAULT_PALETTE = {
        background: 0x1a1a2e,
        fog: 0x1a1a2e,
        ambient: 0.45,
        dir: 0xffffff,
        dirIntensity: 0.9,
        primary: 0xff6b6b,
        secondary: 0x667eea,
        floor: 0x2a2a3e
    };

    const PRIVATE_PALETTE = {
        background: 0x240008,
        fog: 0x240008,
