// Najika Digivice – Three.js scene manager with KayKit rooms, character controls and camera modes
(function () {
    const CAMERA_MODES = {
        ORBIT: 'orbit',
        THIRD: 'third',
        FIRST: 'first'
    };

    const DEFAULT_PALETTE = {
        background: 0x1a1a2e,
        fog: 0x1a1a2e,
        ambient: 0.45,
        dir: 0xffffff,
        dirIntensity: 0.9,
        primary: 0xff6b6b,
        secondary: 0x667eea,
        floor: 0x2a2a3e
    };

    const PRIVATE_PALETTE = {
        background: 0x240008,
        fog: 0x240008,
        ambient: 0.25,
        dir: 0xff5500,
        dirIntensity: 0.6,
        primary: 0xaa1111,
        secondary: 0x330033,
        floor: 0x240008
    };

    const FALLBACK_DEFAULTS = {
        span: 24,
        wallHeight: 6
    };

    const CHARACTER_SPEED = 7.5;
    const CHARACTER_HEIGHT = 3.8;
    const CLAMP_PADDING = 2;

    let scene;
    let camera;
    let renderer;
    let ambientLight;
    let dirLight;
    let pointLight1;
    let pointLight2;
    let baseFloor;
    let gridHelper;
    const fallbackWalls = [];

    let roomGroup = null;
    let currentRoomName = 'Wohnzimmer';
    let currentRoomSpan = FALLBACK_DEFAULTS.span;
    let privateModeActive = false;
    let usingFallbackRoom = true;
    let pendingRoomBuild = false;

    let clock;
    let animationHandle = null;

    let characterGroup = null;
    let characterReady = false;
    let characterHeading = 0;
