        });
        const wallThickness = 1;
        const wallHeight = FALLBACK_DEFAULTS.wallHeight;
        const wallSpan = FALLBACK_DEFAULTS.span;
        const positions = [
            { pos: [0, wallHeight / 2, -wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
            { pos: [0, wallHeight / 2, wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
