        const fg = parseInt(palette.fog.replace('#', ''), 16);
        applyPalette({
            background: bg,
            fog: fg,
            ambient: palette.ambient,
            primary: parseInt(palette.primary.replace('#', ''), 16),
            secondary: parseInt(palette.secondary.replace('#', ''), 16),
            floor: parseInt(palette.floor.replace('#', ''), 16)
        });
